# ==============================================================================# 099A_PAYMENT_ENGINE.py## IOTEC PAYMENT ENGINE## Missão:# Confirmar pagamentos e liberar o reconhecimento da receita.## ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class PaymentEngine:    VALID_METHODS = {        "PIX",        "TED",        "DOC",        "BOLETO",        "CREDIT_CARD",        "DEBIT_CARD",        "CASH"    }    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row    # ------------------------------------------------------------------    def _sha(self,obj):        raw=json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def confirm_payment(        self,        billing_uuid,        payment_method="PIX"    ):        if payment_method not in self.VALID_METHODS:            raise RuntimeError("Forma de pagamento inválida.")        billing=self.conn.execute("""            SELECT *            FROM commercial_billings            WHERE billing_uuid=?            LIMIT 1        """,(billing_uuid,)).fetchone()        if billing is None:            raise RuntimeError("Cobrança não encontrada.")        if billing["status"]=="PAID":            raise RuntimeError("Cobrança já está paga.")        payload={            "paid_at":datetime.utcnow().isoformat(),            "payment_method":payment_method,            "status":"PAID"        }        assinatura=self._sha(payload)        self.conn.execute("""        UPDATE commercial_billings        SET            paid_at=?,            payment_method=?,            status=?,            hash=?        WHERE billing_uuid=?        """,(            payload["paid_at"],            payload["payment_method"],            payload["status"],            assinatura,            billing_uuid        ))        self.conn.commit()        resultado=dict(billing)        resultado.update(payload)        resultado["hash"]=assinatura        return resultado# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    conn=sqlite3.connect(DB)    conn.row_factory=sqlite3.Row    billing=conn.execute("""        SELECT billing_uuid        FROM commercial_billings        WHERE status='PENDING'        LIMIT 1    """).fetchone()    if billing is None:        raise RuntimeError("Nenhuma cobrança pendente encontrada.")    engine=PaymentEngine()    resultado=engine.confirm_payment(        billing_uuid=billing["billing_uuid"],        payment_method="PIX"    )    print("="*80)    print("PAYMENT ENGINE")    print("="*80)    print(f"billing_uuid      : {resultado['billing_uuid']}")    print(f"status            : {resultado['status']}")    print(f"payment_method    : {resultado['payment_method']}")    print(f"paid_at           : {resultado['paid_at']}")    print(f"hash              : {resultado['hash']}")    print("="*80)